     1	#!/bin/bash
     2	# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
     3	set -u
     4	BOOKINGS=${BOOKINGS:-data/bookings.tsv}
     5	[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
     6	room=
     7	if [ "${1:-}" = --room ]; then room=$2; shift 2; fi
     8	grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort
---
     1	# roombook
     2	会議室の予約。`bash src/book.sh <部屋> <日付> <開始> <終了> <名前>` で予約し、`bash src/list.sh [日付]` で一覧を出す。`src/remind.sh` は一覧の出力を読んでリマインドを作る。
---
     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
     4	[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
     5	[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
     6	bash src/list.sh --room >/dev/null 2>&1; [ $? = 2 ] || { echo "--room without a value should exit 2"; fail=1; }
     7	rm -f "$t"; exit $fail
---
